DO $source_identity_cover$BEGIN IF pg_get_indexdef('public.accounting_tournament_source_identity_keys_cover'::regclass)IS DISTINCT FROM $source_cover_definition$CREATE INDEX accounting_tournament_source_identity_keys_cover ON public.accounting_tournament_fee_sources USING btree (id) INCLUDE (tournament_id, rake_record_id)$source_cover_definition$ OR NOT EXISTS(SELECT FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_am am ON am.oid=c.relam WHERE i.indexrelid='public.accounting_tournament_source_identity_keys_cover'::regclass AND i.indrelid='public.accounting_tournament_fee_sources'::regclass AND c.relowner='postgres'::regrole AND c.relkind='i'AND am.amname='btree'AND i.indisvalid AND i.indisready AND i.indislive AND NOT i.indisunique AND i.indnkeyatts=1 AND i.indnatts=3 AND i.indexprs IS NULL AND i.indpred IS NULL)THEN RAISE EXCEPTION 'selected_source_exact_existing_identity_cover_required';END IF;END$source_identity_cover$;
DO $existing_rake_cover$BEGIN IF pg_get_indexdef('public.rake_records_tournament_small_evidence_cover'::regclass)IS DISTINCT FROM $definition$CREATE INDEX rake_records_tournament_small_evidence_cover ON public.rake_records USING btree (tournament_id, id) INCLUDE (hand_id, table_id, club_id, rake_amount, bbj_contribution, pot_size, num_players, created_at, player_contributions, global_hand_id, is_tournament, source, metadata, rake_method, returned_uncalled) WHERE (is_tournament AND (((((COALESCE(octet_length(jsonb_send(metadata)), 0))::bigint + (COALESCE(octet_length(jsonb_send(player_contributions)), 0))::bigint) + (COALESCE(octet_length(jsonb_send(returned_uncalled)), 0))::bigint) <= 448) AND ((((COALESCE(smarter_private.rake_record_jsonb_raw_size(metadata), 0))::bigint + (COALESCE(smarter_private.rake_record_jsonb_raw_size(player_contributions), 0))::bigint) + (COALESCE(smarter_private.rake_record_jsonb_raw_size(returned_uncalled), 0))::bigint) <= 1864) AND (((COALESCE(octet_length(source), 0))::bigint + (COALESCE(octet_length(rake_method), 0))::bigint) <= 128) AND ((((COALESCE(octet_length(numeric_send(rake_amount)), 0))::bigint + (COALESCE(octet_length(numeric_send(bbj_contribution)), 0))::bigint) + (COALESCE(octet_length(numeric_send(pot_size)), 0))::bigint) <= 128)))$definition$OR NOT EXISTS(SELECT FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_am a ON a.oid=c.relam WHERE i.indexrelid='public.rake_records_tournament_small_evidence_cover'::regclass AND i.indrelid='public.rake_records'::regclass AND c.relowner='postgres'::regrole AND a.amname='btree'AND i.indisvalid AND i.indisready AND i.indislive)THEN RAISE EXCEPTION 'quality_cover_existing_physical_index_changed';END IF;END$existing_rake_cover$;
DO $existing_rake_cover$BEGIN IF pg_get_indexdef('public.rake_records_tournament_large_evidence_keys'::regclass)IS DISTINCT FROM $definition$CREATE INDEX rake_records_tournament_large_evidence_keys ON public.rake_records USING btree (tournament_id, id) WHERE (is_tournament AND (NOT (((((COALESCE(octet_length(jsonb_send(metadata)), 0))::bigint + (COALESCE(octet_length(jsonb_send(player_contributions)), 0))::bigint) + (COALESCE(octet_length(jsonb_send(returned_uncalled)), 0))::bigint) <= 448) AND ((((COALESCE(smarter_private.rake_record_jsonb_raw_size(metadata), 0))::bigint + (COALESCE(smarter_private.rake_record_jsonb_raw_size(player_contributions), 0))::bigint) + (COALESCE(smarter_private.rake_record_jsonb_raw_size(returned_uncalled), 0))::bigint) <= 1864) AND (((COALESCE(octet_length(source), 0))::bigint + (COALESCE(octet_length(rake_method), 0))::bigint) <= 128) AND ((((COALESCE(octet_length(numeric_send(rake_amount)), 0))::bigint + (COALESCE(octet_length(numeric_send(bbj_contribution)), 0))::bigint) + (COALESCE(octet_length(numeric_send(pot_size)), 0))::bigint) <= 128))))$definition$OR NOT EXISTS(SELECT FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_am a ON a.oid=c.relam WHERE i.indexrelid='public.rake_records_tournament_large_evidence_keys'::regclass AND i.indrelid='public.rake_records'::regclass AND c.relowner='postgres'::regrole AND a.amname='btree'AND i.indisvalid AND i.indisready AND i.indislive)THEN RAISE EXCEPTION 'quality_cover_existing_physical_index_changed';END IF;END$existing_rake_cover$;
